<?php
namespace App\Features\Stock\Enums;
enum StockStatus:string {case Available='available';case LowStock='low_stock';case OutOfStock='out_of_stock';public function label():string{return match($this){self::Available=>'Tersedia',self::LowStock=>'Stok Menipis',self::OutOfStock=>'Habis'};}public function badgeClass():string{return match($this){self::Available=>'badge-green',self::LowStock=>'badge-yellow',self::OutOfStock=>'badge-red'};}public static function fromQuantity(int $quantity,int $minimum):self{return $quantity<=0?self::OutOfStock:($quantity<=$minimum?self::LowStock:self::Available);}}
